BEGIN; CREATE TEMP TABLE measured ("id" uuid DEFAULT uuidv7() NOT NULL,"tenant_id" uuid NOT NULL,"user_id" uuid NOT NULL,"token_hash" character varying(64) NOT NULL,"user_agent_hash" character varying(64),"created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,"dropped_slot_7" integer,"expires_at" timestamp with time zone NOT NULL);ALTER TABLE measured DROP COLUMN "dropped_slot_7";CREATE INDEX measured_index_0 ON measured USING btree (tenant_id, user_id, expires_at);CREATE UNIQUE INDEX measured_index_1 ON measured USING btree (id);CREATE UNIQUE INDEX measured_index_2 ON measured USING btree (tenant_id, token_hash);INSERT INTO measured(tenant_id,user_id,token_hash,user_agent_hash,expires_at) SELECT '00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000002',md5(i::text)||md5('token-'||i::text),repeat('a',64),'2026-11-10T00:00:00Z' FROM generate_series(1,10000) n(i); SELECT json_build_object('rows',count(*),'avg_tuple_bytes',avg(pg_column_size(d)),'heap_bytes',pg_table_size('measured'),'index_bytes',pg_indexes_size('measured'),'total_bytes',pg_total_relation_size('measured'),'dropped_slots',(SELECT count(*) FROM pg_attribute WHERE attrelid='measured'::regclass AND attnum>0 AND attisdropped)) FROM measured d; ROLLBACK;